        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (4 * stride)));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride)));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride)));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (4 * stride)));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (3 * stride) - 3));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 2));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 2));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (3 * stride) + 3));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (3 * stride) + 3));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 2));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 2));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (3 * stride) - 3));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (4 * stride) + 1));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 1));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 1));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (4 * stride) - 1));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (4 * stride) - 1));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 1));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 1));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (4 * stride) + 1));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - stride - 4));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - stride - 2));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + stride + 2));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + stride + 4));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index + stride - 4));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index + stride - 2));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index - stride + 2));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index - stride + 4));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (3 * stride) - 2));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 1));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 1));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (3 * stride) + 2));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (3 * stride) + 2));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 1));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 1));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (3 * stride) - 2));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 3));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - stride - 2));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + stride + 2));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 3));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 3));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - stride + 2));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + stride - 2));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 3));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 4));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index + stride - 2));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index - stride + 2));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 4));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 4));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - stride - 2));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + stride + 2));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 4));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (4 * stride) - 2));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 1));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 1));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (4 * stride) + 2));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector256.LoadUnsafe(ref source, (uint)(index - (4 * stride) + 2));
        sample1 = Vector256.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 1));
        sample2 = center;
        sample3 = Vector256.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 1));
        sample4 = Vector256.LoadUnsafe(ref source, (uint)(index + (4 * stride) - 2));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector256.MultiplyAddEstimate(sum, sum, result);

        return result;
    }

    /// <summary>
    /// Evaluates the ordered low-frequency Malta rays. Each result belongs to one independent center.
    /// </summary>
    /// <param name="samples">The borrowed plane or zero-padded neighborhood, starting at its logical origin.</param>
    /// <param name="index">The first center's sample index. Its full four-sample halo and all result lanes must exist.</param>
    /// <param name="stride">The physical row stride in samples.</param>
    /// <returns>The sum of the 16 squared ray responses in native order.</returns>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static Vector512<float> MaltaUnitLf512(ReadOnlySpan<float> samples, int index, int stride)
    {
        ref float source = ref MemoryMarshal.GetReference(samples);
        Vector512<float> center = Vector512.LoadUnsafe(ref source, (uint)(index));
        Vector512<float> sum;
        Vector512<float> sample0;
        Vector512<float> sample1;
        Vector512<float> sample2;
        Vector512<float> sample3;
        Vector512<float> sample4;

        // Sample offsets describe the ray, not lane positions. Each load keeps adjacent result centers in lane order.
        // The nested additions retain native Sum's balanced groups; only successive squared rays use multiply-add.
        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - 4));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - 2));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + 2));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + 4));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        Vector512<float> result = sum * sum;

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (4 * stride)));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride)));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride)));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (4 * stride)));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (3 * stride) - 3));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 2));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 2));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (3 * stride) + 3));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (3 * stride) + 3));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 2));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 2));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (3 * stride) - 3));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (4 * stride) + 1));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 1));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 1));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (4 * stride) - 1));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (4 * stride) - 1));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 1));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 1));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (4 * stride) + 1));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - stride - 4));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - stride - 2));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + stride + 2));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + stride + 4));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index + stride - 4));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index + stride - 2));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index - stride + 2));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index - stride + 4));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (3 * stride) - 2));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 1));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 1));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (3 * stride) + 2));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (3 * stride) + 2));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 1));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 1));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (3 * stride) - 2));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 3));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - stride - 2));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + stride + 2));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 3));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 3));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - stride + 2));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + stride - 2));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 3));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 4));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index + stride - 2));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index - stride + 2));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 4));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 4));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - stride - 2));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + stride + 2));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 4));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (4 * stride) - 2));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) - 1));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) + 1));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (4 * stride) + 2));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        sample0 = Vector512.LoadUnsafe(ref source, (uint)(index - (4 * stride) + 2));
        sample1 = Vector512.LoadUnsafe(ref source, (uint)(index - (2 * stride) + 1));
        sample2 = center;
        sample3 = Vector512.LoadUnsafe(ref source, (uint)(index + (2 * stride) - 1));
        sample4 = Vector512.LoadUnsafe(ref source, (uint)(index + (4 * stride) - 2));
        sum = ((sample0 + sample1) + (sample2 + (sample3 + sample4)));
        result = Vector512.MultiplyAddEstimate(sum, sum, result);

        return result;
    }

    /// <summary>
    /// Accumulates low-frequency Malta responses over the prepared difference plane.
    /// </summary>
    /// <param name="differences">The borrowed prepared differences at the plane's logical origin.</param>
    /// <param name="width">The logical width, at least eight samples as established by comparison setup.</param>
    /// <param name="height">The logical height, at least eight rows as established by comparison setup.</param>
    /// <param name="differenceStride">The physical difference-plane stride in samples.</param>
    /// <param name="output">The existing accumulation storage, at the plane's logical origin.</param>
    /// <param name="outputStride">The physical output stride in samples.</param>
    /// <param name="border">The reusable 81-sample zero-padded neighborhood.</param>
    private static void AccumulateMaltaLf(
        ReadOnlySpan<float> differences,
        int width,
        int height,
        int differenceStride,
        Span<float> output,
        int outputStride,
        Span<float> border)
    {
        // Comparison setup expands small inputs to at least 8 by 8. These top and bottom strips contain every center
        // whose four-row halo crosses an edge. Their scalar kernel reads the same 9-by-9 zero extension as native.
        int y = 0;
        for (; y < 4; y++)
        {
            Span<float> outputRow = output.Slice(y * outputStride, width);
            for (int x = 0; x < width; x++)
            {
                PrepareMaltaBorder(differences, width, height, differenceStride, x, y, border);
                outputRow[x] += MaltaUnitLfScalar(border, 40, 9);
            }
        }

        for (; y < height - 4; y++)
        {
            ref float outputRow = ref MemoryMarshal.GetReference(output.Slice(y * outputStride, width));
            int rowIndex = y * differenceStride;
            int x = 0;
            for (; x < 4; x++)
            {
                PrepareMaltaBorder(differences, width, height, differenceStride, x, y, border);
                Unsafe.Add(ref outputRow, x) += MaltaUnitLfScalar(border, 40, 9);
            }

            // Loads are unaligned. Start at the first real interior center rather than reserving an alignment strip.
            // The rightmost lane and its four-column halo must remain inside the logical width, not row padding.
            if (Vector512.IsHardwareAccelerated)
            {
                for (; x <= width - 4 - Vector512<float>.Count; x += Vector512<float>.Count)
                {
                    Vector512<float> previous = Vector512.LoadUnsafe(ref outputRow, (uint)x);
                    Vector512<float> response = MaltaUnitLf512(differences, rowIndex + x, differenceStride);
                    (previous + response).StoreUnsafe(ref outputRow, (uint)x);
                }
            }

            if (Vector256.IsHardwareAccelerated)
            {
                for (; x <= width - 4 - Vector256<float>.Count; x += Vector256<float>.Count)
                {
                    Vector256<float> previous = Vector256.LoadUnsafe(ref outputRow, (uint)x);
                    Vector256<float> response = MaltaUnitLf256(differences, rowIndex + x, differenceStride);
                    (previous + response).StoreUnsafe(ref outputRow, (uint)x);
                }
            }

            if (Vector128.IsHardwareAccelerated)
            {
                for (; x <= width - 4 - Vector128<float>.Count; x += Vector128<float>.Count)
                {
                    Vector128<float> previous = Vector128.LoadUnsafe(ref outputRow, (uint)x);
                    Vector128<float> response = MaltaUnitLf128(differences, rowIndex + x, differenceStride);
                    (previous + response).StoreUnsafe(ref outputRow, (uint)x);
                }
            }

            for (; x < width - 4; x++)
            {
                Unsafe.Add(ref outputRow, x) += MaltaUnitLfScalar(differences, rowIndex + x, differenceStride);
            }

            for (; x < width; x++)
            {
                PrepareMaltaBorder(differences, width, height, differenceStride, x, y, border);
                Unsafe.Add(ref outputRow, x) += MaltaUnitLfScalar(border, 40, 9);
            }
        }

        for (; y < height; y++)
        {
            Span<float> outputRow = output.Slice(y * outputStride, width);
            for (int x = 0; x < width; x++)
            {
                PrepareMaltaBorder(differences, width, height, differenceStride, x, y, border);
                outputRow[x] += MaltaUnitLfScalar(border, 40, 9);
            }
        }
    }

